/**
Shortened code:
t=0,draw=(o=>{for(t||createCanvas(W=600,W),background(0,10),a=1;a<1e3;a+=2.215)x=a*cos(t)**3,y=a*sin(t)**3,strokeWeight(Math.max(0.1, Math.abs((500-a)))/250),stroke((1e3-a)/100*150),point(x+W/2,y+W/2),point(x,y),point(x,y+W),point(x+W,y),point(x+W,y+W),t+=.2});
---
Tweet:
https://twitter.com/KomaTebe/status/1437505582542606338?s=20
*/

document.querySelector("body").style.backgroundColor="#000";

function setup() {
  createCanvas(600, 600);
  t = 0.1;
}

function draw() {
  background(0, 10);

  for (let a = 1; a < 1000; a += 2.215) {
    let x = a * (cos(t)**3);
    let y = a * (sin(t)**3);

    strokeWeight(Math.max(0.1, Math.abs(Math.max(0.5, Math.abs((500 - a))) / 250)));
    stroke(((1000 - a) / 100) * 150);

    point(x + 300, y + 300);
    point(x, y);
    point(x, y + 600);
    point(x + 600, y);
    point(x + 600, y + 600);

    t += 0.2;
  }
}

